import json,collections,re,subprocess
from pathlib import Path
from html import escape as e
ROOT=Path(__file__).resolve().parents[1]
snap=json.loads(Path('/tmp/cmd-revision-current.json').read_text());ps=snap['products'];visible={p['id'] for p in snap['catalogProducts']}
preserve={'gift-visit','gift-season','gift-personal','halloween-bandana','elf-hat','birthday-bandana'}
giftdeps={'mouse','rope','rabbit','creamy-treats','crunchy-treats','pure-treats','halloween-bandana','elf-hat','birthday-bandana'}
active={'window-hammock','scratch-arch','rope','puzzle'}
# Review only - this script writes audit artifacts, never changes storefront modules
rows=[]
for p in ps:
 im=p.get('image');studio=isinstance(im,dict) and im.get('presentation')=='editorial';variants=p.get('variants') or [p]
 studio=studio and all(isinstance(v.get('image'),dict) and v['image'].get('presentation')=='editorial' for v in variants)
 concept=not p.get('isReal');shown=p['id'] in visible
 status='Макет' if concept else 'Студийное изображение' if studio else 'Реальный товар - старое фото'
 if p['id'] in preserve:decision='Оставить по указанию пользователя';reason='Подарочный набор или праздничный аксессуар - исключение из будущей очистки'
 elif not shown:decision='Скрыт - проверить зависимости';reason='Не удалять автоматически - может участвовать в подарках или подборках'
 elif concept:decision='Кандидат на скрытие';reason='Условный макет CatManDog без подтверждённого реального товара'
 elif not studio and p['category']=='Окна и балконы':decision='Подобрать замену / подтвердить поставку';reason='Реальный Trixie из Grupo Trixder, старое фото - закупка не подтверждена'
 elif not studio:decision='Кандидат на скрытие';reason='Старый визуал и товар не входит в согласованную текущую подборку'
 else:decision='Оставить';reason='Студийный визуал подключён - это не подтверждение наличия или закупочной цены'
 deps=[]
 if p['id'] in giftdeps:deps.append('Подарки / состав набора')
 if p['id'] in active:deps.append('Дом для активного кота')
 source=p.get('supplier') or p.get('productSource') or {}
 rows.append({'id':p['id'],'name':p['name'],'brand':p.get('brand','CatManDog'),'category':'Наполнители и лотки' if p['category'] in ['Наполнитель','Лотки и гигиена'] else p['category'],'visible':shown,'isReal':not concept,'studio':bool(studio),'status':status,'decision':decision,'reason':reason,'dependencies':deps,'variants':len(variants),'image':im,'sourceName':source.get('name'),'sourceUrl':source.get('url'),'protected':p['id'] in preserve})
vis=[r for r in rows if r['visible']];cats={}
for r in vis:
 c=cats.setdefault(r['category'],dict(total=0,studio=0,oldReal=0,concept=0,protected=0));c['total']+=1;c['studio']+=int(r['studio'] and r['isReal']);c['oldReal']+=int(not r['studio'] and r['isReal']);c['concept']+=int(not r['isReal']);c['protected']+=int(r['protected'])
checks={}
for key in ['id','ean']:
 found=collections.defaultdict(list)
 for p in snap['catalogProducts']:
  if p.get(key):found[p[key]].append(p['id'])
 checks[key]=[{key:k,'products':v} for k,v in found.items() if len(v)>1]
byvariant=collections.defaultdict(list)
for p in snap['catalogProducts']:
 for v in p.get('variants') or [p]:
  if v.get('ean'):byvariant[v['ean']].append({'parent':p['id'],'variant':v['id']})
checks['variantEAN']=[{'ean':k,'matches':v} for k,v in byvariant.items() if len(v)>1]
report={'date':'2026-10-16','scope':'Текущая локальная витрина, включая ещё не запушенные товары Yagu','commit':subprocess.check_output(['git','rev-parse','--short','HEAD'],text=True).strip(),'storefrontModified':False,'totalRecords':len(rows),'visibleCards':len(vis),'studioRealCards':sum(r['studio'] and r['isReal'] for r in vis),'oldRealCards':sum(not r['studio'] and r['isReal'] for r in vis),'visibleConcepts':sum(not r['isReal'] for r in vis),'protectedVisibleConcepts':len(preserve),'conceptCandidates':sum(not r['isReal'] and not r['protected'] for r in vis),'hiddenRecords':len(rows)-len(vis),'categories':cats,'duplicates':checks,'imageChecks':json.loads(Path('/tmp/cmd-audit-image-check.json').read_text()),'browserChecks':json.loads(Path('/tmp/cmd-audit-browser.json').read_text()),'products':rows}
out=ROOT/'research/catalog-visual-audit-2026-10-16';out.with_suffix('.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
def thumb(r):
 im=r['image']
 if isinstance(im,dict):return '<img loading="lazy" src="../'+e(im['src'])+'" alt="'+e(r['name'])+'">'
 if isinstance(im,str):return '<img loading="lazy" src="../'+e(im)+'" alt="'+e(r['name'])+'">'
 if isinstance(im,int):return '<span class="sprite" style="background-image:url(../assets/products-cats-'+str(im//8+1)+'.png);background-position:'+str(im%4*100/3)+'% '+str(im%8//4*100)+'%"></span>'
 return ''
def cards(items):
 return '<div class="cards">'+''.join('<article>'+thumb(r)+'<div><h3>'+e(r['name'])+'</h3><p>'+e(r['category'])+' / '+e(r['brand'])+'</p><p><b>'+e(r['decision'])+'</b></p><p>'+e(r['reason'])+'</p>'+('<p>Источник: <a target="_blank" rel="noopener" href="'+e(r['sourceUrl'])+'">'+e(r['sourceName'])+'</a></p>' if r['sourceUrl'] else '')+('<p>Зависимости: '+e(', '.join(r['dependencies']))+'</p>' if r['dependencies'] else '')+'<a href="http://127.0.0.1:5173/#/product/'+e(r['id'])+'">Открыть товар</a><small>'+e(r['id'])+'</small></div></article>' for r in items)+'</div>'
cathtml=''.join(f'<tr><th>{e(c)}</th><td>{v["total"]}</td><td>{v["studio"]}</td><td>{v["oldReal"]}</td><td>{v["concept"]}</td><td>{v["protected"]}</td></tr>' for c,v in cats.items())
registry=''.join('<tr data-search="'+e((r['name']+' '+r['id']+' '+r['brand']).lower())+'" data-category="'+e(r['category'])+'" data-state="'+e(r['status'])+'" data-visible="'+str(r['visible']).lower()+'"><td><a href="http://127.0.0.1:5173/#/product/'+e(r['id'])+'">'+e(r['name'])+'</a><small>'+e(r['id'])+'</small></td><td>'+e(r['category'])+'</td><td>'+e(r['status'])+'</td><td>'+('Виден' if r['visible'] else 'Скрыт')+'</td><td>'+e(r['decision'])+'</td><td>'+e(', '.join(r['dependencies']))+'</td></tr>' for r in rows)
css='''body{font:15px/1.55 system-ui;color:#252a24;background:#fafaf7;margin:0}main{max-width:1360px;margin:auto;padding:40px 24px}h1{font-size:clamp(30px,5vw,48px);line-height:1.1}h2{margin-top:48px}h3{font-size:17px;line-height:1.35}a{color:#45602b}small{display:block;color:#72766f;overflow-wrap:anywhere}.metrics{display:flex;gap:12px;flex-wrap:wrap}.metrics div{padding:18px;background:#edf0e3;border-radius:14px;flex:1;min-width:120px}.metrics b{display:block;font-size:32px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;background:white;text-align:left;font-size:14px}td,th{padding:12px;border-bottom:1px solid #e1e4db;vertical-align:top}th{font-weight:600}td:first-child{min-width:220px}.note{background:#f2ecd9;padding:20px;border-radius:14px}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.cards article{background:white;border:1px solid #e5e7de;border-radius:16px;overflow:hidden}.cards article>div{padding:18px}.cards img,.sprite{display:block;width:100%;height:230px;object-fit:contain;background:white}.sprite{background-size:400% 200%}input,select{font:inherit;border:1px solid #ccd1c6;padding:10px;border-radius:8px;max-width:100%}.filters{display:flex;flex-wrap:wrap;gap:12px;margin:20px 0}[hidden]{display:none}@media(max-width:800px){.cards{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:500px){main{padding:24px 16px}.cards{grid-template-columns:1fr}}'''
body=f'''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CatManDog - визуальная ревизия 16 октября 2026</title><style>{css}</style><main><p>CatManDog / 16 октября 2026 / локальная витрина</p><h1>Студийный визуал и реальные товары</h1><p>Ревизия без удаления, скрытия или изменения товаров<br>Включены последние локальные добавления Yagu - опубликованная версия может отличаться</p><div class="metrics"><div><b>{len(vis)}</b>видимых карточек</div><div><b>{report['studioRealCards']}</b>реальных со студийными фото</div><div><b>{report['oldRealCards']}</b>реальных со старыми фото</div><div><b>14</b>обычных видимых макетов</div><div><b>6</b>подарочных исключений</div><div><b>11</b>скрытых макетов</div></div><h2>По категориям</h2><div class="scroll"><table><tr><th>Категория</th><th>Всего</th><th>Реальные студийные</th><th>Реальные старые фото</th><th>Макеты</th><th>Из них сохраняем</th></tr>{cathtml}</table></div><p>Категория «Наполнители и лотки» объединяет две внутренние категории данных - так же, как интерфейс магазина</p><h2>Что уже готово</h2><p>Все 251 карточка корма и 22 карточки лакомств используют студийные изображения, включая варианты<br>Вся подключённая линейка Ownat, 11 семейств Heybo Pet, новые Yagu и подготовленные реальные товары ухода оформлены студийно<br>Серый визуал не подтверждает наличие, финальную розничную цену или доступность закупки</p><h2>29 реальных товаров со старыми фото</h2><p>Кандидаты на последующую очистку витрины по текущему направлению пользователя - не список на новую генерацию<br>4 товара Trixie в разделе окон и балконов требуют отдельного решения о реальной поставке или замене<br>Источники ниже - ранее сохранённые в проекте, актуальность наличия сегодня не перепроверялась</p>{cards([r for r in vis if r['isReal'] and not r['studio']])}<h2>14 обычных макетов - кандидаты на скрытие</h2><p>Эти товары могут уже выглядеть студийно, но остаются выдуманными позициями CatManDog<br>В отличие от реальных товаров со старыми фото, проблема здесь в ассортименте, а не в фоне</p>{cards([r for r in vis if not r['isReal'] and not r['protected']])}<h2>6 подарочных исключений - сохраняем</h2>{cards([r for r in vis if r['protected']])}<h2>Зависимости вне основного каталога</h2><div class="note"><p>Главная страница при первоначальном открытии показывает Переноску Weekend и сетку Trixie<br>В подборке «Наши фавориты» также зафиксированы старые TarHong Boho, KONG Scrunchie, Catit PIXI, Trixie и greenPAWS</p><p>«Дом для активного кота» использует оконную лежанку Trixie и скрытые макеты Arch, Loop и Sense</p><p>Подарки используют скрытые мышку Cotton, зайчика Sage, удочку Loop и условные лакомства Creamy, Crunchy и Pure<br>Удаление этих записей до пересборки состава может сломать наборы и расчёт цены</p><p>Избранное и сохранённые корзины могут ссылаться на старые ID - при будущей очистке скрытие карточек безопаснее физического удаления записей</p></div><h2>11 скрытых макетов</h2>{cards([r for r in rows if not r['visible']])}<h2>Проверки и границы ревизии</h2><ul><li>Проверены данные всех {len(rows)} записей, все варианты и пути к изображениям</li><li>370 уникальных файлов изображений существуют и читаются, студийные файлы квадратные</li><li>В браузере проверены счётчики всех категорий, главная, подарки и страница активного дома - ошибок выполнения не найдено</li><li>29 старых фотографий просмотрены визуально, студийные товары сверены по метаданным и подключённым файлам - не по повторной ручной оценке каждой упаковки</li><li>Точных повторов ID и заполненных EAN карточек: {len(checks['id'])} / {len(checks['ean'])}</li><li>Герой, иллюстрации категорий, баннеры и фотографии журнала не являются SKU и не требуют серого студийного фона</li><li>Ничего не удалено, не скрыто, не перегенерировано и не запушено в рамках этой ревизии</li></ul><h2>Полный реестр</h2><div class="filters"><input id="q" aria-label="Поиск" placeholder="Название, бренд или ID"><select id="cat" aria-label="Категория"><option value="">Все категории</option>{''.join('<option>'+e(c)+'</option>' for c in cats)}</select><select id="state" aria-label="Статус"><option value="">Все статусы</option><option>Студийное изображение</option><option>Реальный товар - старое фото</option><option>Макет</option></select><select id="visibility" aria-label="Видимость"><option value="">Все записи</option><option value="true">Видимые</option><option value="false">Скрытые</option></select></div><p id="count">{len(rows)} записей</p><div class="scroll"><table id="registry"><thead><tr><th>Товар</th><th>Категория</th><th>Визуал / происхождение</th><th>Видимость</th><th>Предложение</th><th>Зависимости</th></tr></thead><tbody>{registry}</tbody></table></div></main><script>const inputs=['q','cat','state','visibility'].map(id=>document.getElementById(id));function filter(){{let n=0;for(const r of document.querySelectorAll('#registry tbody tr')){{r.hidden=!(r.dataset.search.includes(inputs[0].value.toLowerCase())&&(!inputs[1].value||r.dataset.category===inputs[1].value)&&(!inputs[2].value||r.dataset.state===inputs[2].value)&&(!inputs[3].value||r.dataset.visible===inputs[3].value));if(!r.hidden)n++}}document.getElementById('count').textContent=n+' записей'}}for(const i of inputs)i.addEventListener('input',filter)</script></html>'''
out.with_suffix('.html').write_text(body)
print(json.dumps({k:report[k] for k in ['totalRecords','visibleCards','studioRealCards','oldRealCards','visibleConcepts','conceptCandidates','hiddenRecords']},ensure_ascii=False))
